type RenderProp<T> = (value: T) => React.ReactNode;

function List<T>({ items, renderItem }: { items: T[]; renderItem: RenderProp<T> }) {
  return <ul>{items.map((it, i) => <li key={i}>{renderItem(it)}</li>)}</ul>;
}
